__d(function(a,t,e,i,s,o,r){s.exports={uri:"/app.book.med.aeroespacial/assets/assets/images/topicos/m1v5-2-tripulacao.874ead0a048674976a06bdd30159fe52.jpg",width:1600,height:893,toString(){return this.uri}}},933,[]);
